//! Complete LoadMonsterProp C2/2C30..2D70, composing native AI/traits/RNG.
use crate::{battle_data::MonsterProperties,battle_actor_stats::{self,MonsterStats,Immunity},battle_rage::Traits,battle_ai::AiTable,battle_rng::{BattleRng,RngTable},battle_scheduler::Scheduler};
use std::{fs,path::Path,collections::BTreeMap};
#[derive(Clone)]pub struct Tables {properties:[MonsterProperties;384],items:[[u8;4];384],names:Vec<u8>,animations:[u8;384],ai:AiTable}
impl Tables {pub fn load(root:&Path)->Result<Self,String> {let dir=root.join("build/native_battle");let read=|name:&str,size|->Result<Vec<u8>,String>{let b=fs::read(dir.join(format!("{name}.bin"))).map_err(|e|format!("Monster load {name}: {e}; run tools/extract_native_monsters.py"))?;if b.len()!=size {return Err(format!("Monster table {name} length mismatch"));}Ok(b)};let raw=read("monster_properties",12288)?;let items=read("monster_items",1536)?;Ok(Self {properties:std::array::from_fn(|i|MonsterProperties {raw:raw[i*32..i*32+32].try_into().unwrap()}),items:std::array::from_fn(|i|items[i*4..i*4+4].try_into().unwrap()),names:read("monster_names",3840)?,animations:read("monster_special_animations",384)?.try_into().unwrap(),ai:AiTable::load(root)?})}
    fn key(&self,id:u16)->Result<&[u8],String> {if id>=384 {return Err("Name grouping monster ID outside target table".into());}let i=usize::from(id)*8;Ok(&self.names[i..i+8])}
}
#[derive(Clone,Copy,Debug)]pub struct Actor {pub monster:u16,pub ai_monster:u16,pub display:u16,pub held:u16,pub ai_normal:u16,pub ai_retaliation:u16,pub defense:u16,pub exp:u16,pub gil:u16,pub hp:u16,pub max_hp:u16,pub mp:u16,pub max_mp:u16,pub stats:MonsterStats,pub traits:Traits,pub animation:u8,pub strength:u8,pub update:u8}
impl Default for Actor {fn default()->Self {Self {monster:65535,ai_monster:65535,display:65535,held:65535,ai_normal:65535,ai_retaliation:65535,defense:0,exp:0,gil:0,hp:0,max_hp:0,mp:0,max_mp:0,stats:MonsterStats {stamina:0,power:0,hand_item:0,evade:0,magic_evade:0,hit_rate:0,level:0,speed:0,magic:0,retal_flags:0,monster_status:0},traits:Traits {special:0,weak_half:0,allowed:[255;4],pending12:0,pending34:0,relic45:0,equip_status23:0,absorb_null:0,metamorph_flags:0},animation:0,strength:0,update:255}}}
#[derive(Clone,Copy,Debug)]pub struct Globals {pub preserve:u16,pub battle:u16,pub doom_hp:u16,pub doom_gaze:u16,pub b1:u8,pub loaded:u8}
pub fn load(slot:usize,id:u16,a:&mut[Actor;10],s:&mut Scheduler,g:&mut Globals,rng:&mut BattleRng,table:&RngTable,t:&Tables)->Result<(),String> {
    if !(4..10).contains(&slot) || id>=384 {return Err("Monster loading requires one of six monster slots and target ID below 384".into());}
    a[slot].monster=id;a[slot].ai_monster=id;let ptr=t.ai.initialize(id,a[slot].ai_retaliation)?;a[slot].ai_normal=ptr.normal;a[slot].ai_retaliation=ptr.retaliation;a[slot].held=u16::from_le_bytes(t.items[usize::from(id)][..2].try_into().unwrap());a[slot].display=id;
    let key=t.key(id)?;for other in (4..10).rev() {let candidate=a[other].monster;if candidate&0x8000==0 && key==t.key(candidate)? {a[slot].display=candidate;break;}}
    let p=&t.properties[usize::from(id)];let actor=&mut a[slot];actor.defense=p.word(5);actor.exp=p.exp();actor.gil=p.gil();
    if g.preserve&0x8000==0 {actor.mp=p.mp();actor.max_mp=p.mp();actor.hp=p.hp();actor.max_hp=p.hp();if g.battle==0x1cf {g.doom_gaze=(slot*2) as u16;if g.doom_hp!=0 {actor.hp=g.doom_hp;}}}
    actor.stats=battle_actor_stats::monster(p,actor.max_hp,actor.stats.retal_flags);actor.traits.apply(p);actor.animation=t.animations[usize::from(id)];
    if actor.stats.monster_status&2!=0 && s.actors[slot].flags0&1!=0 {s.actors[slot].flags0|=8;s.actors[slot].gauge.counter&=255;s.actors[slot].gauge.advance_counter|=0xff00;s.enqueue_advance(slot);g.b1|=128;}
    actor.strength=56+(rng.next(table)&7);
    let mut immune=Immunity {allowed:actor.traits.allowed,protection:s.actors[slot].flags1};immune.fix_death_poison((actor.traits.absorb_null>>8) as u8);actor.traits.allowed=immune.allowed;s.actors[slot].flags1=immune.protection;Ok(())
}
#[derive(Clone,Copy,Debug)]pub struct Formation {pub raw:[u8;15],pub colosseum:u8,pub opponent:u8}
/// Complete InitMonsters caller: establish all present bits before descending loads.
pub fn initialize(f:Formation,a:&mut[Actor;10],s:&mut Scheduler,g:&mut Globals,rng:&mut BattleRng,table:&RngTable,t:&Tables)->Result<(),String> {
    for index in 0..6 {s.actors[index+4].flags0=(f.raw[1]>>index)&1;}
    for index in (0..6).rev() {g.loaded=g.loaded.wrapping_shl(1);let high=(f.raw[14]>>index)&1;
        let id=if f.colosseum&128!=0 {if high!=0 {continue;}u16::from(f.opponent)}else{u16::from(f.raw[index+2])|(u16::from(high)<<8)};
        if id==511 {continue;}load(index+4,id,a,s,g,rng,table,t)?;if a[index+4].traits.equip_status23&1!=0 {a[index+4].update&=!16;}g.loaded=g.loaded.wrapping_add(1);
    }Ok(())
}
fn formation_snapshot(f:Formation)->String {use std::fmt::Write;let mut out=String::new();for (i,v) in f.raw.iter().enumerate() {write!(out,"{:06X}{v:02X}",0x7e3f44+i).unwrap();}write!(out,"7E3A97{:02X}7E0206{:02X}",f.colosseum,f.opponent).unwrap();out}
fn snapshot(a:&[Actor;10],s:&Scheduler,g:&Globals,rng:&BattleRng)->String {
    let mut m=BTreeMap::<u32,u8>::new();let mut put=|addr:u32,value:u16,width:usize|{for i in 0..width {m.insert(addr+i as u32,(value>>(i*8)) as u8);}};
    for (slot,actor) in a.iter().enumerate() {let x=slot as u32*2;let stats=actor.stats;let t=actor.traits;let sc=s.actors[slot];
        for (addr,value,width) in [(0x33a8,actor.ai_monster,2),(0x3380,actor.display,2),(0x3308,actor.held,2),(0x3254,actor.ai_normal,2),(0x3268,actor.ai_retaliation,2),(0x3bb8,actor.defense,2),(0x3d84,actor.exp,2),(0x3d98,actor.gil,2),(0x3bf4,actor.hp,2),(0x3c1c,actor.max_hp,2),(0x3c08,actor.mp,2),(0x3c30,actor.max_mp,2),(0x3b40,u16::from(stats.stamina),1),(0x3b68,u16::from(stats.power),1),(0x3ca8,u16::from(stats.hand_item),1),(0x3b54,u16::from(stats.evade),1),(0x3b55,u16::from(stats.magic_evade),1),(0x3b7c,u16::from(stats.hit_rate),1),(0x3b18,u16::from(stats.level),1),(0x3b19,u16::from(stats.speed),1),(0x3b41,u16::from(stats.magic),1),(0x3e4c,u16::from(stats.retal_flags),1),(0x3c80,u16::from(stats.monster_status),1),(0x3c81,u16::from(actor.animation),1),(0x3b2c,u16::from(actor.strength),1),(0x3204,u16::from(actor.update),1),(0x322d,u16::from(t.special),1),(0x3be0,t.weak_half,2),(0x331c,u16::from_le_bytes(t.allowed[..2].try_into().unwrap()),2),(0x3330,u16::from_le_bytes(t.allowed[2..].try_into().unwrap()),2),(0x3dd4,t.pending12,2),(0x3de8,t.pending34,2),(0x3c58,t.relic45,2),(0x3c6c,t.equip_status23,2),(0x3bcc,t.absorb_null,2),(0x3c94,t.metamorph_flags,2),(0x3aa0,u16::from(sc.flags0),1),(0x3aa1,u16::from(sc.flags1),1),(0x3218,sc.gauge.counter,2),(0x3ab4,sc.gauge.advance_counter,2)] {put(0x7e0000+addr+x,value,width);}
        if slot>=4 {put(0x7e1ff9+x,actor.monster,2);}
    }
    for (addr,value,width) in [(0x3a46,g.preserve,2),(0x3ed4,g.battle,2),(0x3ebe,g.doom_hp,2),(0x33fa,g.doom_gaze,2),(0x3a73,u16::from(g.loaded),1),(0xb1,u16::from(g.b1),1),(0xbe,u16::from(rng.index),1),(0x3a64,u16::from(s.queues.advance.head),1),(0x3a65,u16::from(s.queues.advance.tail),1)] {put(0x7e0000+addr,value,width);}for (i,v) in s.queues.advance.bytes.iter().enumerate() {put(0x7e3720+i as u32,u16::from(*v),1);}
    m.iter().map(|(addr,v)|format!("{addr:06X}{v:02X}")).collect()
}
pub fn capture(root:&Path,dir:&Path)->Result<(),String> {
    use std::fmt::Write;fs::create_dir_all(dir).map_err(|e|e.to_string())?;let t=Tables::load(root)?;let table=RngTable::load(root)?;let mut seed=0x6ff6u32;let mut rows=String::from("case,slot,id,before,after\n");
    for case in 0..2304usize {let mut next=||{seed=seed.wrapping_mul(1664525).wrapping_add(1013904223);(seed>>16) as u8};let id=(case%384) as u16;let n=case/384;let slot=4+n;let mut a=[Actor::default();10];let mut s=Scheduler::default();
        for i in 0..10 {a[i].monster=if i<4 || i%3==0 {65535}else{u16::from(next())%384};a[i].display=u16::from_le_bytes([next(),next()]);a[i].ai_monster=u16::from_le_bytes([next(),next()]);a[i].held=u16::from_le_bytes([next(),next()]);a[i].ai_normal=u16::from_le_bytes([next(),next()]);a[i].ai_retaliation=u16::from_le_bytes([next(),next()]);a[i].hp=u16::from_le_bytes([next(),next()]);a[i].max_hp=u16::from_le_bytes([next(),next()]);a[i].mp=u16::from_le_bytes([next(),next()]);a[i].max_mp=u16::from_le_bytes([next(),next()]);a[i].traits=Traits {special:next(),weak_half:u16::from_le_bytes([next(),next()]),allowed:std::array::from_fn(|_|next()),pending12:u16::from_le_bytes([next(),next()]),pending34:u16::from_le_bytes([next(),next()]),relic45:u16::from_le_bytes([next(),next()]),equip_status23:u16::from_le_bytes([next(),next()]),absorb_null:u16::from_le_bytes([next(),next()]),metamorph_flags:u16::from_le_bytes([next(),next()])};a[i].stats.retal_flags=next();a[i].update=next();s.actors[i].flags0=(next()&254)|u8::from(n%2==0);s.actors[i].flags1=next();s.actors[i].gauge.counter=u16::from_le_bytes([next(),next()]);s.actors[i].gauge.advance_counter=u16::from_le_bytes([next(),next()]);}
        if slot!=9 {a[9].monster=(0..384).find(|other|*other!=id && t.key(*other).unwrap()==t.key(id).unwrap()).unwrap_or(id);}
        s.queues.advance.head=next();s.queues.advance.tail=next();s.queues.advance.bytes=std::array::from_fn(|_|next());let mut g=Globals {preserve:[0,32768,65535,32767,0,32768][n],battle:if n==2 || n==4 {0x1cf}else{2},doom_hp:if case%3==0 {0}else{u16::from_le_bytes([next(),next()])},doom_gaze:u16::from_le_bytes([next(),next()]),b1:next(),loaded:next()};let mut rng=BattleRng {index:next()};let before=snapshot(&a,&s,&g,&rng);load(slot,id,&mut a,&mut s,&mut g,&mut rng,&table,&t)?;writeln!(rows,"{case},{slot},{id},{before},{}",snapshot(&a,&s,&g,&rng)).unwrap();
    }fs::write(dir.join("monsters.csv"),rows).map_err(|e|e.to_string())?;
    let bytes=fs::read(root.join("build/native_battle/formation_monsters.bin")).map_err(|e|e.to_string())?;if bytes.len()!=8640 {return Err("Formation monster table length mismatch".into());}
    let mut rows=String::from("case,before,after\n");
    for case in 0..704usize {let raw=bytes[case%576*15..case%576*15+15].try_into().unwrap();let f=Formation {raw,colosseum:if case>=576 {255}else{0},opponent:case as u8};let mut a=[Actor::default();10];for actor in &mut a {actor.traits.equip_status23=(case&1) as u16;}let mut s=Scheduler::default();let mut g=Globals {preserve:if case%5==0 {32768}else{0},battle:if case%17==0 {0x1cf}else{case as u16},doom_hp:(case*11) as u16,doom_gaze:65535,b1:case as u8,loaded:case as u8};let mut rng=BattleRng {index:case as u8};let before=snapshot(&a,&s,&g,&rng)+&formation_snapshot(f);initialize(f,&mut a,&mut s,&mut g,&mut rng,&table,&t)?;writeln!(rows,"{case},{before},{}",snapshot(&a,&s,&g,&rng)+&formation_snapshot(f)).unwrap();}
    fs::write(dir.join("formations.csv"),rows).map_err(|e|e.to_string())
}
#[cfg(test)]mod tests {
    use super::*;
    fn tables()->Tables {Tables::load(Path::new("extracted/twue-3.07")).unwrap()}
    fn globals()->Globals {Globals {preserve:0,battle:2,doom_hp:0,doom_gaze:65535,b1:0,loaded:0}}
    #[test]fn guard_loads_real_items_stats_and_consumes_one_strength_draw() {let t=tables();let mut a=[Actor::default();10];let mut s=Scheduler::default();let mut rng=BattleRng {index:255};load(6,0,&mut a,&mut s,&mut globals(),&mut rng,&RngTable::identity(),&t).unwrap();assert_eq!((a[6].hp,a[6].mp,a[6].exp,a[6].gil,a[6].held),(40,15,48,48,u16::from_le_bytes([233,232])));assert_eq!((a[6].stats.speed,a[6].stats.level,a[6].stats.magic,a[6].strength,rng.index),(30,5,9,56,0));}
    #[test]fn preserve_flag_keeps_all_resources_but_reloads_other_properties() {let mut a=[Actor::default();10];a[4].hp=3;a[4].max_hp=1234;a[4].mp=5;a[4].max_mp=6;let mut s=Scheduler::default();let mut g=Globals {preserve:32768,battle:0x1cf,doom_hp:99,..globals()};load(4,0,&mut a,&mut s,&mut g,&mut BattleRng::default(),&RngTable::identity(),&tables()).unwrap();assert_eq!((a[4].hp,a[4].max_hp,a[4].mp,a[4].max_mp,g.doom_gaze),(3,1234,5,6,65535));assert_eq!(a[4].stats.stamina,18);}
    #[test]fn doom_gaze_override_changes_current_hp_only() {let mut a=[Actor::default();10];let mut g=Globals {battle:0x1cf,doom_hp:7,..globals()};load(7,0,&mut a,&mut Scheduler::default(),&mut g,&mut BattleRng::default(),&RngTable::identity(),&tables()).unwrap();assert_eq!((a[7].hp,a[7].max_hp,a[7].mp,g.doom_gaze),(7,40,15,14));}
    #[test]fn first_strike_updates_source_queue_and_preserves_low_gauges() {let mut t=tables();t.properties[0].raw[19]|=2;let mut a=[Actor::default();10];let mut s=Scheduler::default();s.actors[6].flags0=1;s.actors[6].flags1=255;s.actors[6].gauge.counter=0xabcd;s.actors[6].gauge.advance_counter=0x1234;let mut g=globals();load(6,0,&mut a,&mut s,&mut g,&mut BattleRng::default(),&RngTable::identity(),&t).unwrap();assert_eq!((s.actors[6].flags0,s.actors[6].gauge.counter,s.actors[6].gauge.advance_counter,g.b1),(9,205,0xff34,128));assert_eq!(s.queues.advance.pop(),Some(12));assert_eq!(s.actors[6].flags1&1,0);}
    #[test]fn equal_name_keys_use_highest_loaded_slot_identity() {let mut t=tables();let key=t.names[..8].to_vec();t.names[8..16].copy_from_slice(&key);let mut a=[Actor::default();10];a[9].monster=1;load(4,0,&mut a,&mut Scheduler::default(),&mut globals(),&mut BattleRng::default(),&RngTable::identity(),&t).unwrap();assert_eq!(a[4].display,1);}
    #[test]fn name_key_stride_remains_eight_despite_ten_byte_display_names() {let t=tables();assert_eq!(t.key(1).unwrap(),&t.names[8..16]);assert_ne!(t.key(1).unwrap(),&t.names[10..18]);}
    #[test]fn opening_formation_loads_both_guards_with_shared_native_rng() {let root=Path::new("extracted/twue-3.07");let t=tables();let data=crate::battle_data::BattleData::load(root).unwrap();let encounter=data.encounter(data.event_formation(1,0).unwrap()).unwrap();let mut a=[Actor::default();10];let mut s=Scheduler::default();let mut rng=BattleRng {index:255};initialize(Formation {raw:encounter.raw_monsters,colosseum:0,opponent:0},&mut a,&mut s,&mut globals(),&mut rng,&RngTable::identity(),&t).unwrap();assert_eq!((a[6].hp,a[7].hp,a[6].strength,a[7].strength,rng.index),(40,40,57,56,1));}
    #[test]fn empty_formation_preserves_actor_data_and_rng_but_replaces_present_bits() {let mut a=[Actor::default();10];a[4].hp=123;let mut s=Scheduler::default();s.actors[4].flags0=255;let mut g=Globals {loaded:3,..globals()};let mut rng=BattleRng {index:7};initialize(Formation {raw:[255;15],colosseum:0,opponent:0},&mut a,&mut s,&mut g,&mut rng,&RngTable::identity(),&tables()).unwrap();assert_eq!((a[4].hp,s.actors[4].flags0,g.loaded,rng.index),(123,1,192,7));}
    #[test]fn low_ff_with_clear_high_bit_is_real_monster_255() {let mut a=[Actor::default();10];let mut raw=[255;15];raw[14]=0;let mut rng=BattleRng {index:7};initialize(Formation {raw,colosseum:0,opponent:0},&mut a,&mut Scheduler::default(),&mut globals(),&mut rng,&RngTable::identity(),&tables()).unwrap();assert!(a[4..].iter().all(|a|a.monster==255));assert_eq!(rng.index,13);}
    #[test]fn colosseum_keeps_formation_high_bits_and_uses_opponent_low_byte() {let mut raw=[255;15];raw[14]=62;let mut a=[Actor::default();10];let mut g=globals();let mut rng=BattleRng::default();initialize(Formation {raw,colosseum:128,opponent:3},&mut a,&mut Scheduler::default(),&mut g,&mut rng,&RngTable::identity(),&tables()).unwrap();assert_eq!((a[4].monster,a[5].monster,g.loaded,rng.index),(3,65535,1,1));}

    #[test]fn patched_formation_helper_disables_condemned_counter_update() {let mut t=tables();t.properties[0].raw[28]|=1;let mut a=[Actor::default();10];a[4].update=255;let mut raw=[255;15];raw[2]=0;raw[14]=62;initialize(Formation {raw,colosseum:0,opponent:0},&mut a,&mut Scheduler::default(),&mut globals(),&mut BattleRng::default(),&RngTable::identity(),&t).unwrap();assert_eq!((a[4].update,a[4].traits.equip_status23&1),(239,1));}

}
